package dev.ftb.mods.ftbechoes.block.entity;

import dev.ftb.mods.ftbechoes.client.FTBEchoesClient;
import dev.ftb.mods.ftbechoes.echo.EchoManager;
import dev.ftb.mods.ftbechoes.entity.EchoEntity;
import dev.ftb.mods.ftbechoes.registry.ModBlockEntityTypes;
import dev.ftb.mods.ftbechoes.registry.ModEntityTypes;
import net.minecraft.core.BlockPos;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.Connection;
import net.minecraft.network.protocol.Packet;
import net.minecraft.network.protocol.game.ClientGamePacketListener;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.util.Util;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.minecraft.world.phys.Vec3;

import javax.annotation.Nullable;
import java.util.UUID;

public class EchoProjectorBlockEntity extends BlockEntity {
    @Nullable private Identifier echoId;
    private UUID workerID = Util.NIL_UUID;

    public EchoProjectorBlockEntity(BlockPos pos, BlockState state) {
        super(ModBlockEntityTypes.ECHO_PROJECTOR.get(), pos, state);
    }

    @Override
    public CompoundTag getUpdateTag(HolderLookup.Provider provider) {
        // server side, chunk sending
        CompoundTag compound = super.getUpdateTag(provider);
        if (echoId != null) compound.putString("echo_id", echoId.toString());
        return compound;
    }

    @Override
    public @Nullable Packet<ClientGamePacketListener> getUpdatePacket() {
        // server side, block update (calls getUpdateTag())
        return ClientboundBlockEntityDataPacket.create(this);
    }

    @Override
    public void handleUpdateTag(ValueInput input) {
        super.handleUpdateTag(input);

        FTBEchoesClient.onProjectorUpdated(this);
    }

    @Override
    public void onDataPacket(Connection net, ValueInput valueInput) {
        handleUpdateTag(valueInput);
    }

    @Override
    protected void loadAdditional(ValueInput input) {
        super.loadAdditional(input);

        echoId = input.read("echo_id", Identifier.CODEC).orElse(null);
    }

    @Override
    protected void saveAdditional(ValueOutput output) {
        super.saveAdditional(output);

        if (echoId != null) {
            output.store("echo_id", Identifier.CODEC, echoId);
        }
    }

    @Nullable
    public Identifier getEchoId() {
        return echoId;
    }

    public void setEchoId(@Nullable Identifier echoId) {
        this.echoId = echoId;
        if (level instanceof ServerLevel serverLevel) {
            createNewEchoEntity();
            setChanged();
            serverLevel.sendBlockUpdated(getBlockPos(), getBlockState(), getBlockState(), Block.UPDATE_ALL);
        }
    }

    @Override
    public void onLoad() {
        if (!level.isClientSide()) {
            createNewEchoEntity();
        }
    }

    private void createNewEchoEntity() {
        EchoManager.getServerInstance().getEcho(getEchoId()).ifPresent(echo -> {
            EchoEntity newEcho = new EchoEntity(ModEntityTypes.ECHO.get(), level);
            newEcho.setNoAi(true);
            newEcho.setSilent(true);
            newEcho.setPos(Vec3.atCenterOf(getBlockPos()));
            newEcho.setEchoId(echo.id());
            newEcho.aiStep();
            echo.model().ifPresent(model -> newEcho.setVillagerData(model.data()));
            level.addFreshEntity(newEcho);
            workerID = newEcho.getUUID();
        });
    }

    public boolean validateEchoEntity(EchoEntity entity) {
        return entity.isAlive()
                && entity.getEchoId().equals(echoId)
                && entity.getUUID().equals(workerID);
    }
}

package dev.ftb.mods.ftbechoes.echo;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import dev.ftb.mods.ftbechoes.FTBEchoes;
import dev.ftb.mods.ftbechoes.util.EchoCodecs;
import dev.ftb.mods.ftbechoes.util.MiscUtil;
import net.minecraft.ChatFormatting;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.ComponentSerialization;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.util.ExtraCodecs;
import net.minecraft.world.item.ItemStackTemplate;

import java.util.List;
import java.util.Optional;
import java.util.function.Consumer;

public record StageCompletionReward(List<ItemStackTemplate> stacks, int exp, int currency, Optional<CommandInfo> command, List<Component> description, boolean autoclaim) {
    public static final Codec<StageCompletionReward> CODEC = RecordCodecBuilder.create(builder -> builder.group(
            EchoCodecs.ITEM_OR_ITEMS_CODEC.optionalFieldOf("item", List.of()).forGetter(StageCompletionReward::stacks),
            ExtraCodecs.NON_NEGATIVE_INT.optionalFieldOf("experience", 0).forGetter(StageCompletionReward::exp),
            ExtraCodecs.NON_NEGATIVE_INT.optionalFieldOf("currency", 0).forGetter(StageCompletionReward::currency),
            CommandInfo.CODEC.optionalFieldOf("command").forGetter(StageCompletionReward::command),
            EchoCodecs.COMPONENT_OR_LIST.optionalFieldOf("description", List.of()).forGetter(StageCompletionReward::description),
            Codec.BOOL.optionalFieldOf("autoclaim", true).forGetter(StageCompletionReward::autoclaim)
    ).apply(builder, StageCompletionReward::new));

    public static final StreamCodec<RegistryFriendlyByteBuf, StageCompletionReward> STREAM_CODEC = StreamCodec.composite(
            ItemStackTemplate.STREAM_CODEC.apply(ByteBufCodecs.list()), StageCompletionReward::stacks,
            ByteBufCodecs.VAR_INT, StageCompletionReward::exp,
            ByteBufCodecs.VAR_INT, StageCompletionReward::currency,
            ByteBufCodecs.optional(CommandInfo.STREAM_CODEC), StageCompletionReward::command,
            ComponentSerialization.STREAM_CODEC.apply(ByteBufCodecs.list()), StageCompletionReward::description,
            ByteBufCodecs.BOOL, StageCompletionReward::autoclaim,
            StageCompletionReward::new
    );

    public void giveToPlayer(ServerPlayer player) {
        stacks.forEach(stack -> player.getInventory().placeItemBackInInventory(stack.create()));
        if (exp > 0) {
            player.giveExperiencePoints(exp);
        }
        if (currency > 0) {
            FTBEchoes.currencyProvider().giveCurrency(player, currency);
        }
        command.ifPresent(cmdInfo -> cmdInfo.runForPlayer(player));
    }

    public void addTooltip(Consumer<Component> consumer) {
        description.forEach(consumer);

        for (ItemStackTemplate stack : stacks) {
            consumer.accept(bullet().append(stack.count() + " x ").append(stack.create().getHoverName()));
        }
        if (exp > 0) {
            consumer.accept(bullet().append(exp + " XP"));
        }
        if (currency > 0) {
            consumer.accept(bullet().append(MiscUtil.formatCost(currency)));
        }
        command.ifPresent(cmd -> cmd.description().forEach(line -> consumer.accept(bullet().append(line))));
    }

    private static MutableComponent bullet() {
        return Component.literal("• ").withStyle(ChatFormatting.AQUA);
    }
}

package dev.ftb.mods.ftbechoes.echo.progress;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.core.UUIDUtil;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.player.Player;
import org.apache.commons.lang3.mutable.MutableInt;
import org.jspecify.annotations.Nullable;

import java.util.*;
import java.util.function.Function;

/**
 * Progress for a given team and echo. Note that mutator methods are package-private (only to be called from
 * {@link TeamProgress}).
 */
public final class PerEchoProgress {
    private static final Codec<Map<UUID, Set<Integer>>> REWARDS_CLAIMED
            = Codec.unboundedMap(UUIDUtil.STRING_CODEC, Codec.INT.listOf().xmap(HashSet::new, ArrayList::new));
    private static final Codec<PerEchoProgress> RAW_CODEC = RecordCodecBuilder.create(builder -> builder.group(
            Codec.INT.xmap(MutableInt::new, m -> m.get().intValue()).fieldOf("current_stage").forGetter(p -> p.currentStage),
            REWARDS_CLAIMED.fieldOf("rewards_claimed").forGetter(p -> p.claimedRewards)
    ).apply(builder, PerEchoProgress::new));
    public static final Codec<PerEchoProgress> CODEC = RAW_CODEC.xmap(
            // ensure claimed rewards map is mutable after loading
            in -> new PerEchoProgress(in.currentStage, new HashMap<>(in.claimedRewards)),
            Function.identity()
    );
    public static final StreamCodec<FriendlyByteBuf, PerEchoProgress> STREAM_CODEC = StreamCodec.composite(
            ByteBufCodecs.VAR_INT.map(MutableInt::new, m -> m.get().intValue()), p -> p.currentStage,
            ByteBufCodecs.map(HashMap::new, UUIDUtil.STREAM_CODEC, ByteBufCodecs.INT.apply(ByteBufCodecs.collection(HashSet::new))), p -> p.claimedRewards,
            PerEchoProgress::new
    );

    private final MutableInt currentStage;
    private final Map<UUID, Set<Integer>> claimedRewards;

    /**
     * @param currentStage   last completed stage for this echo (0 indicates team are on first stage, no completions yet)
     * @param claimedRewards the echo rewards claimed by each player on the team, by player UUID
     */
    public PerEchoProgress(MutableInt currentStage, Map<UUID, Set<Integer>> claimedRewards) {
        this.currentStage = currentStage;
        this.claimedRewards = claimedRewards;
    }

    public static PerEchoProgress createEmptyProgress() {
        return new PerEchoProgress(new MutableInt(0), new HashMap<>());
    }

    public int getCurrentStage() {
        return currentStage.intValue();
    }

    void setCurrentStage(int stage) {
        currentStage.setValue(stage);
    }

    public boolean isRewardClaimed(Player player, int stage) {
        return claimedRewards.getOrDefault(player.getUUID(), Set.of()).contains(stage);
    }

    boolean setRewardClaimed(UUID playerId, int stage, boolean claimed) {
        Set<Integer> s = claimedRewards.computeIfAbsent(playerId, _ -> new HashSet<>());
        return claimed ? s.add(stage) : s.remove(stage);
    }

    boolean clearRewards(UUID playerId) {
        Set<Integer> s = claimedRewards.computeIfAbsent(playerId, _ -> new HashSet<>());
        boolean hadAnyRewards = !s.isEmpty();
        s.clear();
        return hadAnyRewards;
    }

    void completeStage() {
        currentStage.increment();
    }

    public PerEchoProgress forSyncToPlayer(ServerPlayer player) {
        UUID playerId = player.getUUID();
        Map<UUID,Set<Integer>> rewards = Map.of(playerId, claimedRewards.getOrDefault(playerId, Set.of()));
        return new PerEchoProgress(new MutableInt(currentStage), rewards);
    }

    @Override
    public boolean equals(@Nullable Object obj) {
        if (obj == this) return true;
        if (obj == null || obj.getClass() != this.getClass()) return false;
        var that = (PerEchoProgress) obj;
        return Objects.equals(this.currentStage, that.currentStage) &&
                Objects.equals(this.claimedRewards, that.claimedRewards);
    }

    @Override
    public int hashCode() {
        return Objects.hash(currentStage, claimedRewards);
    }

    @Override
    public String toString() {
        return "PerEchoProgress[" +
                "currentStage=" + currentStage + ", " +
                "claimedRewards=" + claimedRewards + ']';
    }
}

package dev.ftb.mods.ftbechoes.echo.progress;

import com.mojang.datafixers.util.Pair;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import dev.ftb.mods.ftbechoes.echo.Echo;
import dev.ftb.mods.ftbechoes.echo.EchoManager;
import dev.ftb.mods.ftbechoes.shopping.ShopData;
import dev.ftb.mods.ftbechoes.shopping.ShoppingKey;
import net.minecraft.core.UUIDUtil;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.util.Mth;
import net.minecraft.util.Util;
import net.minecraft.world.entity.player.Player;
import org.apache.commons.lang3.mutable.MutableBoolean;

import java.util.*;
import java.util.function.Function;

/**
 * Progress for a given team. The record members are mutable internally, but only modified
 * by mutator methods called via {@link TeamProgressManager}.
 *
 * @param perEcho progress on an echo, by echo ID
 */
public record TeamProgress(
        Map<Identifier, PerEchoProgress> perEcho,
        Map<ShoppingKey, Integer> stockLimit,
        Map<UUID,Map<ShoppingKey, Integer>> playerStockLimit
) {
    public static final TeamProgress NONE = new TeamProgress(Map.of(), Map.of(), Map.of());

    private static final Codec<Map<Identifier,PerEchoProgress>> ECHO_STAGE
            = Codec.unboundedMap(Identifier.CODEC, PerEchoProgress.CODEC).xmap(HashMap::new, Map::copyOf);
    private static final Codec<Map<ShoppingKey, Integer>> LIMITED_PURCHASE_CODEC
            = Codec.list(Codec.pair(ShoppingKey.CODEC.fieldOf("key").codec(), Codec.INT.fieldOf("count").codec()))
            .xmap(TeamProgress::toMap, TeamProgress::toList);
    public static final StreamCodec<FriendlyByteBuf, Map<ShoppingKey,Integer>> LIMITED_PURCHASE_STREAM_CODEC
            = ByteBufCodecs.map(HashMap::new, ShoppingKey.STREAM_CODEC, ByteBufCodecs.VAR_INT);

    public static final Codec<TeamProgress> RAW_CODEC = RecordCodecBuilder.create(builder -> builder.group(
            ECHO_STAGE.fieldOf("per_echo")
                    .forGetter(TeamProgress::perEcho),
            LIMITED_PURCHASE_CODEC.optionalFieldOf("limited_shop_purchases", new HashMap<>())
                    .forGetter(TeamProgress::stockLimit),
            Codec.unboundedMap(UUIDUtil.STRING_CODEC, LIMITED_PURCHASE_CODEC).optionalFieldOf("limited_per_player", new HashMap<>())
                    .forGetter(TeamProgress::playerStockLimit)
    ).apply(builder, TeamProgress::new));

    public static final Codec<TeamProgress> CODEC = RAW_CODEC.xmap(
            // ensure maps are mutable after loading
            in -> new TeamProgress(new HashMap<>(in.perEcho), new HashMap<>(in.stockLimit), new HashMap<>(in.playerStockLimit)),
            Function.identity()
    );

    public static final StreamCodec<FriendlyByteBuf, TeamProgress> STREAM_CODEC = StreamCodec.composite(
            ByteBufCodecs.map(HashMap::new, Identifier.STREAM_CODEC, PerEchoProgress.STREAM_CODEC), TeamProgress::perEcho,
            ByteBufCodecs.map(HashMap::new, ShoppingKey.STREAM_CODEC, ByteBufCodecs.INT), p -> p.stockLimit,
            ByteBufCodecs.map(HashMap::new, UUIDUtil.STREAM_CODEC, LIMITED_PURCHASE_STREAM_CODEC), p -> p.playerStockLimit,
            TeamProgress::new
    );

    private static <K,V> Map<K,V> toMap(List<Pair<K,V>> list) {
        return Util.make(new HashMap<>(), map -> list.forEach(pair -> map.put(pair.getFirst(), pair.getSecond())));
    }

    private static <K,V> List<Pair<K,V>> toList(Map<K,V> map) {
        return Util.make(new ArrayList<>(), list -> map.forEach((k,v) -> list.add(Pair.of(k, v))));
    }

    public static TeamProgress createNew() {
        return new TeamProgress(new HashMap<>(), new HashMap<>(), new HashMap<>());
    }

    public TeamProgress forSyncTo(ServerPlayer player) {
        Map<Identifier, PerEchoProgress> map = Util.make(new HashMap<>(), m ->
                perEcho.forEach((id, rec) -> m.put(id, rec.forSyncToPlayer(player)))
        );
        Map<UUID,Map<ShoppingKey,Integer>> playerLimit = Util.make(new HashMap<>(), m ->
                m.put(player.getUUID(), playerStockLimit.getOrDefault(player.getUUID(), new HashMap<>()))
        );
        return new TeamProgress(map, stockLimit, playerLimit);
    }

    @Override
    public Map<Identifier, PerEchoProgress> perEcho() {
        return Collections.unmodifiableMap(perEcho);
    }

    @SuppressWarnings("BooleanMethodIsAlwaysInverted")
    public boolean isRewardClaimed(Identifier echoId, Player player, int stage) {
        return getPerEchoProgress(echoId).isRewardClaimed(player, stage);
    }

    public int getCurrentStage(Identifier echoId) {
        return getPerEchoProgress(echoId).getCurrentStage();
    }

    public boolean isStageCompleted(Identifier id, int stageIdx) {
        return stageIdx < getCurrentStage(id);
    }

    public int getRemainingShopStock(Player player, ShoppingKey key, ShopData data) {
        return data.maxClaims()
                .map(max -> max - getLimitMap(player, data).getOrDefault(key, 0))
                .orElse(Integer.MAX_VALUE);
    }

    public List<Pair<Echo,Integer>> checkForAutoclaim(ServerPlayer sp) {
        List<Pair<Echo,Integer>> res = new ArrayList<>();

        perEcho.keySet().forEach(id -> EchoManager.getServerInstance().getEcho(id).ifPresent(echo -> {
            for (int stage = 0; stage < echo.stages().size(); stage++) {
                if (echo.stages().get(stage).isAutoclaimReward() && isStageCompleted(echo.id(), stage)) {
                    if (claimReward(id, sp, stage)) {
                        res.add(Pair.of(echo, stage));
                    }
                }
            }
        }));

        return res;
    }

    /****************************************************************************************
     * mutator methods below here are package-private and only called via TeamProgressManager
     */

    void consumeShopStock(Player player, ShoppingKey key, int count, ShopData data) {
        getLimitMap(player, data).merge(key, count, Integer::sum);
    }

    boolean resetShopStock(Identifier echoId) {
        MutableBoolean removed = new MutableBoolean(stockLimit.entrySet().removeIf(e -> e.getKey().echoId().equals(echoId)));

        playerStockLimit.values().forEach(map -> {
            if (map.entrySet().removeIf(e -> e.getKey().echoId().equals(echoId))) {
                removed.setTrue();
            }
        });

        return removed.get();
    }

    boolean resetAllRewards(Identifier echoId, UUID playerId) {
        return getPerEchoProgress(echoId).clearRewards(playerId);
    }

    boolean resetReward(Identifier echoId, UUID playerId, int stageIdx) {
        return getPerEchoProgress(echoId).setRewardClaimed(playerId, stageIdx, false);
    }

    boolean claimReward(Identifier echoId, ServerPlayer player, int stage) {
        if (isRewardClaimed(echoId, player, stage)) {
            return false;
        }
        return EchoManager.getServerInstance().getEcho(echoId).map(echo -> {
            if (stage >= 0 && stage < echo.stages().size()) {
                echo.stages().get(stage).completionReward().ifPresent(c -> c.giveToPlayer(player));
                return getPerEchoProgress(echoId).setRewardClaimed(player.getUUID(), stage, true);
            }
            return false;
        }).orElse(false);
    }

    boolean completeStage(Echo echo) {
        PerEchoProgress per = getPerEchoProgress(echo.id());
        if (per.getCurrentStage() < echo.stages().size()) {
            per.completeStage();
            return true;
        }
        return false;
    }

    boolean setStage(Identifier echoId, int stageIdx) {
        PerEchoProgress per = getPerEchoProgress(echoId);
        var echo = EchoManager.getServerInstance().getEcho(echoId).orElseThrow();
        per.setCurrentStage(Mth.clamp(stageIdx, 0, echo.stages().size()));
        return true;
    }

    private PerEchoProgress getPerEchoProgress(Identifier echoId) {
        return perEcho.computeIfAbsent(echoId, _ -> PerEchoProgress.createEmptyProgress());
    }

    private Map<ShoppingKey, Integer> getLimitMap(Player player, ShopData data) {
        return data.perPlayerMax() ?
                playerStockLimit.computeIfAbsent(player.getUUID(), _ -> new HashMap<>()) :
                stockLimit;
    }
}

package dev.ftb.mods.ftbechoes.echo.progress;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import dev.ftb.mods.ftbechoes.FTBEchoes;
import dev.ftb.mods.ftbechoes.echo.Echo;
import dev.ftb.mods.ftbechoes.echo.EchoStage;
import dev.ftb.mods.ftbechoes.net.ClaimRewardResponseMessage;
import dev.ftb.mods.ftbechoes.net.SyncProgressMessage;
import dev.ftb.mods.ftbechoes.shopping.ShopData;
import dev.ftb.mods.ftbechoes.shopping.ShoppingKey;
import dev.ftb.mods.ftbechoes.util.MiscUtil;
import dev.ftb.mods.ftbteams.api.FTBTeamsAPI;
import dev.ftb.mods.ftbteams.api.Team;
import net.minecraft.ChatFormatting;
import net.minecraft.core.UUIDUtil;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.chat.Component;
import net.minecraft.network.protocol.game.ClientboundSoundPacket;
import net.minecraft.resources.Identifier;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.level.saveddata.SavedData;
import net.minecraft.world.level.saveddata.SavedDataType;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.network.PacketDistributor;

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.function.Function;

public class TeamProgressManager extends SavedData {
//    private static final String SAVE_NAME = FTBEchoes.MOD_ID + "_progress";

    // serialization!  using xmap here, so we get mutable hashmaps in the live manager
    private static final Codec<Map<UUID, TeamProgress>> PROGRESS_CODEC
            = Codec.unboundedMap(UUIDUtil.STRING_CODEC, TeamProgress.CODEC).xmap(HashMap::new, Map::copyOf);

    public static final Codec<TeamProgressManager> CODEC = RecordCodecBuilder.create(builder -> builder.group(
            PROGRESS_CODEC.fieldOf("progress").forGetter(mgr -> mgr.progressMap)
    ).apply(builder, TeamProgressManager::new));

    public static final SavedDataType<TeamProgressManager> TYPE
            = new SavedDataType<>(FTBEchoes.id("progress"), TeamProgressManager::createNew, CODEC);

    // keyed by Team ID (not player ID)
    private final Map<UUID, TeamProgress> progressMap;

    private TeamProgressManager(Map<UUID,TeamProgress> progressMap) {
        this.progressMap = progressMap;
    }

    public static TeamProgressManager get(MinecraftServer server) {
        return server.getDataStorage().computeIfAbsent(TYPE);
    }

    private static TeamProgressManager createNew() {
        return new TeamProgressManager(new HashMap<>());
    }

    public Optional<TeamProgress> getProgress(ServerPlayer sp) {
        return FTBTeamsAPI.api().getManager().getTeamForPlayer(sp).map(this::getProgress);
    }

    public TeamProgress getProgress(Team team) {
        return progressMap.computeIfAbsent(team.getTeamId(), k -> newProgress());
    }

    public boolean claimReward(ServerPlayer player, Identifier echoId, int stageIdx) {
        return applyChange(player, progress -> progress.claimReward(echoId, player, stageIdx));
    }

    public boolean setStage(ServerPlayer player, Identifier echoId, int stageIdx) {
        return applyChange(player, progress -> progress.setStage(echoId, stageIdx));
    }

    public boolean setStage(Team team, Identifier echoId, int stageIdx) {
        return applyChange(team, progress -> progress.setStage(echoId, stageIdx));
    }

    public boolean resetReward(UUID playerId, Identifier echoId, int stageIdx) {
        return applyChange(playerId, progress -> progress.resetReward(echoId, playerId, stageIdx));
    }

    public void tryCompleteStage(ServerPlayer sp, Team team, Echo echo) {
        TeamProgress teamProgress = TeamProgressManager.get(sp.level().getServer()).getProgress(team);
        final int currentStage = teamProgress.getCurrentStage(echo.id());

        if (currentStage >= 0 && currentStage < echo.stages().size()) {
            EchoStage stage = echo.stages().get(currentStage);
            if (MiscUtil.hasStage(sp, team, stage.requiredGameStage())) {
                stage.completionReward().ifPresent(reward -> {
                    if (reward.autoclaim()) {
                        if (teamProgress.claimReward(echo.id(), sp, currentStage)) {
                            PacketDistributor.sendToPlayer(sp, SyncProgressMessage.forPlayer(teamProgress, sp));
                            PacketDistributor.sendToPlayer(sp, new ClaimRewardResponseMessage(true, Optional.ofNullable(stage.completionRewardSummary())));
                            setDirty();
                        } else {
                            FTBEchoes.LOGGER.error("reward claim failed for echo {}, player {}, stage {}", echo.id(), sp.getGameProfile().name(), stage);
                        }
                    }
                });
                if (completeStage(team, echo)) {
                    notifyTeamCompletion(team, echo, currentStage);
                }
            }
        }
    }

    private void notifyTeamCompletion(Team team, Echo echo, int currentStage) {
        team.getOnlineMembers().forEach(member -> {
            Vec3 vec = member.position();
            Component echoTitle = echo.title().copy().withStyle(ChatFormatting.YELLOW);
            Component stageTitle = echo.stages().get(currentStage).title().copy().withStyle(ChatFormatting.YELLOW);
            member.sendSystemMessage(Component.translatable("ftbechoes.message.echo_stage_complete", echoTitle, stageTitle).withStyle(ChatFormatting.GREEN));
            if (currentStage == echo.stages().size() - 1) {
                member.sendSystemMessage(Component.translatable("ftbechoes.message.echo_complete", echoTitle).withStyle(ChatFormatting.LIGHT_PURPLE));
                member.connection.send(new ClientboundSoundPacket(BuiltInRegistries.SOUND_EVENT.wrapAsHolder(SoundEvents.UI_TOAST_CHALLENGE_COMPLETE),
                        SoundSource.PLAYERS, vec.x, vec.y, vec.z, 1f, 1f, 0L));
            } else {
                member.connection.send(new ClientboundSoundPacket(BuiltInRegistries.SOUND_EVENT.wrapAsHolder(SoundEvents.PLAYER_LEVELUP),
                        SoundSource.PLAYERS, vec.x, vec.y, vec.z, 1f, 1f, 0L));
            }
        });
    }

    private boolean completeStage(Team team, Echo echo) {
        return applyChange(team, progress -> progress.completeStage(echo));
    }

    public boolean resetAllRewards(UUID playerId, Identifier echoId) {
        return applyChange(playerId, progress -> progress.resetAllRewards(echoId, playerId));
    }

    public void consumeLimitedShopPurchase(ServerPlayer player, ShoppingKey key, int count, ShopData shopData) {
        applyChange(player, progress -> {
            progress.consumeShopStock(player, key, count, shopData);
            return true;
        });
    }

    public boolean resetShopStock(ServerPlayer player, Identifier echoId) {
        return applyChange(player, progress -> progress.resetShopStock(echoId));
    }

    public boolean resetShopStock(Team team, Identifier echoId) {
        return applyChange(team, progress -> progress.resetShopStock(echoId));
    }

    private boolean applyChange(UUID playerId, Function<TeamProgress, Boolean> task) {
        return FTBTeamsAPI.api().getManager().getTeamForPlayerID(playerId)
                .map(team -> applyChange(team, task))
                .orElse(false);
    }

    private boolean applyChange(ServerPlayer player, Function<TeamProgress, Boolean> task) {
        return FTBTeamsAPI.api().getManager().getTeamForPlayer(player)
                .map(team -> applyChange(team, task))
                .orElse(false);
    }

    private boolean applyChange(Team team, Function<TeamProgress, Boolean> task) {
        FTBEchoes.LOGGER.debug("applyChange: team='{}' teamId={} getId={} mapSize={}",
                team.getShortName(), team.getTeamId(), team.getId(), progressMap.size());
        TeamProgress teamProgress = progressMap.computeIfAbsent(team.getTeamId(), k -> newProgress());
        if (task.apply(teamProgress)) {
            setDirty();
            team.getOnlineMembers().forEach(player ->
                    PacketDistributor.sendToPlayer(player, SyncProgressMessage.forPlayer(teamProgress, player))
            );
            return true;
        }
        return false;
    }

    private TeamProgress newProgress() {
        setDirty();
        return TeamProgress.createNew();
    }

    public void injectProgressData(UUID teamId, TeamProgress progress) {
        // called via the /ftbechoes nbtedit command
        progressMap.put(teamId, progress);
        setDirty();
        FTBTeamsAPI.api().getManager().getTeamByID(teamId)
                .ifPresent(team -> team.getOnlineMembers().forEach(sp ->
                        PacketDistributor.sendToPlayer(sp, SyncProgressMessage.forPlayer(progress, sp)))
                );
    }
}

