package dev.ftb.mods.ftbechoes.shopping;

import com.mojang.serialization.Codec;
import com.mojang.serialization.DataResult;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import dev.ftb.mods.ftbechoes.echo.CommandInfo;
import dev.ftb.mods.ftbechoes.echo.progress.TeamProgressManager;
import dev.ftb.mods.ftbechoes.util.EchoCodecs;
import dev.ftb.mods.ftblibrary.icon.Icon;
import dev.ftb.mods.ftblibrary.util.NetworkHelper;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.ComponentSerialization;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.util.ExtraCodecs;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.ItemStackTemplate;
import org.jspecify.annotations.Nullable;

import java.util.List;
import java.util.Objects;
import java.util.Optional;

public record ShopData(String name, List<ItemStackTemplate> stacks, int cost, List<Component> description, Optional<Icon<?>> icon, Optional<CommandInfo> command, Optional<Integer> maxClaims, boolean perPlayerMax, int maxStage) {
    private static final Codec<ShopData> RAW_CODEC = RecordCodecBuilder.create(builder -> builder.group(
            Codec.STRING.fieldOf("name").forGetter(ShopData::name),
            EchoCodecs.ITEM_OR_ITEMS_CODEC.optionalFieldOf("item", List.of()).forGetter(ShopData::stacks),
            ExtraCodecs.POSITIVE_INT.optionalFieldOf("cost", 1).forGetter(ShopData::cost),
            EchoCodecs.COMPONENT_OR_LIST.optionalFieldOf("description", List.of()).forGetter(ShopData::description),
            Icon.STRING_CODEC.optionalFieldOf("icon").forGetter(ShopData::icon),
            CommandInfo.CODEC.optionalFieldOf("command").forGetter(ShopData::command),
            Codec.INT.optionalFieldOf("max_claims").forGetter(ShopData::maxClaims),
            Codec.BOOL.optionalFieldOf("per_player_max_claims", false).forGetter(ShopData::perPlayerMax),
            Codec.INT.optionalFieldOf("max_stage", Integer.MAX_VALUE).forGetter(ShopData::maxStage)
    ).apply(builder, ShopData::new));

    public static final Codec<ShopData> CODEC = RAW_CODEC.validate(ShopData::validate);

    public static final StreamCodec<RegistryFriendlyByteBuf, ShopData> STREAM_CODEC = NetworkHelper.composite(
            ByteBufCodecs.STRING_UTF8, ShopData::name,
            ItemStackTemplate.STREAM_CODEC.apply(ByteBufCodecs.list()), ShopData::stacks,
            ByteBufCodecs.VAR_INT, ShopData::cost,
            ComponentSerialization.STREAM_CODEC.apply(ByteBufCodecs.list()), ShopData::description,
            ByteBufCodecs.optional(Icon.STREAM_CODEC), ShopData::icon,
            ByteBufCodecs.optional(CommandInfo.STREAM_CODEC), ShopData::command,
            ByteBufCodecs.optional(ByteBufCodecs.VAR_INT), ShopData::maxClaims,
            ByteBufCodecs.BOOL, ShopData::perPlayerMax,
            ByteBufCodecs.VAR_INT, ShopData::maxStage,
            ShopData::new
    );

    private DataResult<ShopData> validate() {
        if (stacks.isEmpty() && (icon.isEmpty() || command.isEmpty())) {
            return DataResult.error(() -> "when item is empty, icon, description and command must all be specified");
        } else if (!stacks.isEmpty() && command.isPresent()) {
            return DataResult.error(() -> "when item is not empty, icon, command must not be specified");
        }
        return DataResult.success(this);
    }

    public void giveTo(ShoppingKey key, ServerPlayer player, int nOrders) {
        for (ItemStackTemplate stack : stacks()) {
            int total = stack.count() * nOrders;
            while (total > 0) {
                ItemStack toGive = stack.withCount(Math.min(total, stack.getMaxStackSize())).create();
                int count = toGive.getCount();
                player.getInventory().placeItemBackInInventory(toGive);
                total -= count;
            }
        }
        command.ifPresent(cmdInfo -> cmdInfo.runForPlayer(player));
        if (maxClaims().isPresent()) {
            TeamProgressManager.get(player.level().getServer()).consumeLimitedShopPurchase(player, key, nOrders, this);
        }
    }

    @Override
    public boolean equals(@Nullable Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        ShopData data = (ShopData) o;
        return Objects.equals(name, data.name);
    }

    @Override
    public int hashCode() {
        return Objects.hashCode(name);
    }
}

package dev.ftb.mods.ftbechoes.shopping;

import com.google.common.collect.Maps;
import dev.ftb.mods.ftbechoes.echo.EchoManager;
import dev.ftb.mods.ftbechoes.echo.progress.TeamProgressManager;
import it.unimi.dsi.fastutil.objects.Object2IntMap;
import it.unimi.dsi.fastutil.objects.Object2IntOpenHashMap;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.server.level.ServerPlayer;
import net.neoforged.neoforge.common.util.Lazy;

import java.util.HashMap;
import java.util.Map;
import java.util.function.BiConsumer;

/**
 * Tracking what player currently has on order from the shop. Also sent to the server by PlaceOrderMessage.
 */
public class ShoppingBasket {
    public static final StreamCodec<FriendlyByteBuf, ShoppingBasket> STREAM_CODEC = StreamCodec.composite(
            ByteBufCodecs.map(Maps::newHashMapWithExpectedSize, ShoppingKey.STREAM_CODEC, ByteBufCodecs.VAR_INT), b -> b.orders,
            ShoppingBasket::new
    );

    private final Object2IntMap<ShoppingKey> orders;
    private final Lazy<Integer> totalCost = Lazy.of(this::calcTotalCost);

    public static final ShoppingBasket CLIENT_INSTANCE = new ShoppingBasket(Map.of());

    private ShoppingBasket(Map<ShoppingKey, Integer> map) {
        orders = new Object2IntOpenHashMap<>(map);
    }

    public void adjust(ShoppingKey key, int count, int max) {
        int newCount = orders.getOrDefault(key, 0) + count;
        if (newCount <= 0) {
            orders.removeInt(key);
        } else {
            orders.put(key, Math.min(max, newCount));
        }
        totalCost.invalidate();
    }

    public int get(ShoppingKey key) {
        return orders.getOrDefault(key, 0);
    }

    public boolean hasContents() {
        return !orders.isEmpty();
    }

    public void clear() {
        orders.clear();
        totalCost.invalidate();
    }

    public void forEach(BiConsumer<ShoppingKey,Integer> consumer) {
        orders.forEach(consumer::accept);
    }

    public int getTotalCost() {
        return totalCost.get();
    }

    public void giveTo(ServerPlayer player) {
        EchoManager mgr = EchoManager.getServerInstance();
        orders.forEach((key, nOrders) -> mgr.getShopData(key).ifPresent(data -> data.giveTo(key, player, nOrders)));
    }

    /**
     * Perform server-side validation of a basket's contents, ensuring only items the player actually has access
     * to (based on their current echo progress) are included.
     *
     * @param player the player to check
     * @return a new basket, including only items the player has unlocked
     */
    public ShoppingBasket validate(ServerPlayer player) {
        Map<ShoppingKey,Integer> map = new HashMap<>();

        TeamProgressManager.get(player.level().getServer()).getProgress(player).ifPresent(progress -> {
            EchoManager mgr = EchoManager.getServerInstance();
            orders.forEach((key, amount) -> mgr.getShoppingEntry(key).ifPresent(entry -> {
                // If the claim is limited, make sure we don't exceed the allowed number
                boolean stockAvailable = entry.data().maxClaims().isEmpty()
                        || progress.getRemainingShopStock(player, key, entry.data()) >= amount;
                int currentStage = progress.getCurrentStage(key.echoId());
                if (stockAvailable && currentStage >= entry.stageIdx() && currentStage <= entry.data().maxStage()) {
                    map.put(key, amount);
                }
            }));
        });

        return new ShoppingBasket(map);
    }

    private int calcTotalCost() {
        int total = 0;
        EchoManager mgr = this == CLIENT_INSTANCE ? EchoManager.getClientInstance() : EchoManager.getServerInstance();
        for (var entry : orders.object2IntEntrySet()) {
            total += mgr.getShopData(entry.getKey()).map(data -> data.cost() * entry.getIntValue()).orElse(0);
        }
        return total;
    }
}

